-- Generated by ekos-lakehouse (RFC 0195) from marts/rentals_by_customer_month.md.
{{ config(materialized='table', schema='gold', alias='rentals_by_customer_month') }}

select
    "customer"."customer_id" as "customer",
    "customer"."email" as "customer_email",
    date_trunc('month', "rental"."rental_date") as "month",
    count("rental"."rental_id") as "rentals",
    sum("payment"."amount") as "revenue"
from {{ ref('public__payment') }} as "payment"
left join {{ ref('public__rental') }} as "rental"
    on "payment"."rental_id" = "rental"."rental_id"
left join {{ ref('public__customer') }} as "customer"
    on "rental"."customer_id" = "customer"."customer_id"
where "rental"."return_date" is not null
group by 1, 2, 3
